rule "unifi-15-extract-mac-addresses"
when
    has_field("unifi_raw_MAC")
then
    let mac = to_string($message.unifi_raw_MAC);

    let parsed = regex(
        "^([0-9a-fA-F]{2}(?::[0-9a-fA-F]{2}){5}):([0-9a-fA-F]{2}(?::[0-9a-fA-F]{2}){5}):([0-9a-fA-F]{2}:[0-9a-fA-F]{2})$",
        mac,
        ["src_mac", "dst_mac", "ether_type"]
    );

    set_field("src_mac", parsed["src_mac"]);
    set_field("dst_mac", parsed["dst_mac"]);
    set_field("ether_type", parsed["ether_type"]);
end

rule "unifi-04-dhcp"
when
    has_field("process_message") &&
    contains(to_string($message.process_message), "DHCP") &&
    has_field("process_name") &&
    to_string($message.process_name) == "dnsmasq-dhcp"
then
    let dhcp = multi_grok(
        patterns: [
            "^%{WORD:dhcp_event}\\(%{NOTSPACE:dhcp_interface}\\) %{NOTSPACE:client_ip} %{NOTSPACE:client_mac}(?: %{GREEDYDATA:client_hostname})?$",
            "^%{WORD:dhcp_event}\\(%{NOTSPACE:dhcp_interface}\\) %{NOTSPACE:client_mac}$"
        ],
        value: to_string($message.process_message),
        only_named_captures: true
    );

    set_fields(dhcp);

    set_field("unifi_log_type", "dhcp");

end

rule "unifi-01-firewall"
when
    has_field("message") &&
    contains(to_string($message.message), " DESCR=\"") &&
    contains(to_string($message.message), " MAC=") &&
    contains(to_string($message.message), " SRC=") &&
    contains(to_string($message.message), " PROTO=")
then
    let msg = to_string($message.message);

    // Extract firewall chain and remaining payload.
    let base = grok(
        pattern: ".*\\[%{DATA:unifi_chain}\\] %{GREEDYDATA:unifi_payload}$",
        value: msg,
        only_named_captures: true
    );

    set_fields(base);

    // Extract quoted firewall description.
    let desc = grok(
        pattern: "DESCR=\"%{DATA:unifi_description}\"",
        value: msg,
        only_named_captures: true
    );

    set_fields(desc);

    // Remove description before parsing key/value pairs.
    let clean_payload = regex_replace(
        "DESCR=\"[^\"]*\"\\s*",
        to_string(base.unifi_payload),
        ""
    );

    // Preserve the first LEN if a second LEN exists.
    let kv = key_value(
        value: clean_payload,
        kv_delimiters: "=",
        ignore_empty_values: true,
        allow_dup_keys: true,
        handle_dup_keys: "take_first"
    );

    // Preserve original extracted values for troubleshooting.
    set_fields(kv, "unifi_raw_");

    set_field("unifi_log_type", "firewall");
    set_field("unifi_event_type", "firewall");

    set_field("src_interface", to_string(kv["IN"]));
    set_field("src_ip", to_ip(to_string(kv["SRC"])));
    set_field("dst_ip", to_ip(to_string(kv["DST"])));
    set_field("protocol", to_string(kv["PROTO"]));

    set_field("src_port", to_long(to_string(kv["SPT"])));
    set_field("dst_port", to_long(to_string(kv["DPT"])));

    set_field("packet_length", to_long(to_string(kv["LEN"])));
    set_field("ttl", to_long(to_string(kv["TTL"])));
    set_field("ip_packet_id", to_long(to_string(kv["ID"])));

    set_field("ip_tos", to_string(kv["TOS"]));
    set_field("ip_precedence", to_string(kv["PREC"]));
    set_field("firewall_mark", to_string(kv["MARK"]));

end

rule "unifi-10-udp-length"
when
    has_field("unifi_chain") &&
    contains(to_string($message.message), "PROTO=UDP") &&
    contains(to_string($message.message), "LEN=")
then
    let udp = grok(
        pattern: ".*PROTO=UDP.*LEN=%{INT:udp_payload_length}.*",
        value: to_string($message.message),
        only_named_captures: true
    );

    set_field(
        "udp_payload_length",
        to_long(to_string(udp.udp_payload_length))
    );
end

rule "unifi-03-cef"
when
    has_field("message") &&
    contains(to_string($message.message), "CEF:0|Ubiquiti|UniFi Network|")
then
    let msg = to_string($message.message);

    // Remove syslog envelope, retaining CEF.
    let cef_text = regex_replace(
        "^.*?(CEF:[0-9]+\\|.*)$",
        msg,
        "$1"
    );

    // Parse CEF using short extension field names.
    let cef_fields = parse_cef(cef_text, false);

    // Keep CEF fields separate from normalized fields.
    set_fields(cef_fields, "cef_");

    set_field("unifi_log_type", "cef_security");

end

rule "unifi-02-process"
when
    has_field("message") &&
    contains(to_string($message.message), "]: ") &&
    (
        contains(to_string($message.message), "dnsmasq-dhcp[") ||
        contains(to_string($message.message), "unifi-mq-broker[")
    )
then
    let msg = to_string($message.message);

    let parsed = grok(
        pattern: ".*%{NOTSPACE:process_name}\\[%{INT:process_id}\\]: %{GREEDYDATA:process_message}$",
        value: msg,
        only_named_captures: true
    );

    set_fields(parsed);

    set_field(
        "process_id",
        to_long(to_string(parsed.process_id))
    );

end

rule "unifi-06-diagnostics"
when
    has_field("process_message") &&
    contains(to_string($message.process_message), "MEM usage")
then
    let stats = key_value(
        value: to_string($message.process_message),
        kv_delimiters: "=",
        ignore_empty_values: true
    );

    set_field("unifi_log_type", "system_diagnostic");

    set_field("memory_flows", to_long(to_string(stats["flows"])));
    set_field("memory_dying", to_long(to_string(stats["dying"])));
    set_field("memory_dns", to_long(to_string(stats["dns"])));
    set_field("memory_ifaces", to_long(to_string(stats["ifaces"])));
    set_field("memory_dns_resolv", to_long(to_string(stats["dnsResolv"])));
    set_field("memory_routines", to_long(to_string(stats["routines"])));

end
